static void rotateMesh(scene::IMesh *mesh, float degrees)
{
{
	degrees *= M_PI / 180.0f;
	degrees *= M_PI / 180.0f;
	float c = std::cos(degrees);
	float c = std::cos(degrees);
	float s = std::sin(degrees);
	float s = std::sin(degrees);
	auto rotator = [c, s] (video::S3DVertex *vertex) {
	auto rotator = [c, s] (video::S3DVertex *vertex) {
		auto rotate_vec = [c, s] (v3f &vec) {
		auto rotate_vec = [c, s] (v3f &vec) {
			float u = vec.*U;
			float u = vec.*U;
			float v = vec.*V;
			float v = vec.*V;
			vec.*U = c * u - s * v;
			vec.*U = c * u - s * v;
			vec.*V = s * u + c * v;
			vec.*V = s * u + c * v;
		};
		};
		rotate_vec(vertex->Pos);
		rotate_vec(vertex->Pos);
		rotate_vec(vertex->Normal);
		rotate_vec(vertex->Normal);
	};
	};
{
	u8 wall = cur_node.n.getWallMounted(nodedef);
	TileSpec tile;
	useTile(&tile, 0, MATERIAL_FLAG_CRACK_OVERLAY, MATERIAL_FLAG_BACKFACE_CULLING);
	static const float offset = BS / 16;
	float size = BS / 2 * cur_node.f->visual_scale;
	// Wall at X+ of node
	v3f vertices[4] = {
		v3f(BS / 2 - offset,  size,  size),
		v3f(BS / 2 - offset,  size, -size),
		v3f(BS / 2 - offset, -size, -size),
		v3f(BS / 2 - offset, -size,  size),
	};

	for (v3f &vertex : vertices) {
		switch (wall) {
			case DWM_YP:
				vertex.rotateXYBy( 90); break;
			case DWM_YN:
