	// reference to a mesh buffer used when rendering the map.
	struct DrawDescriptor {
		v3f m_pos; // world translation
		bool m_reuse_material:1;
		bool m_use_partial_buffer:1;
		union {
			scene::IMeshBuffer *m_buffer;
