void MapblockMeshGenerator::drawFirelikeQuad(const TileSpec &tile, float rotation,
		float opening_angle, float offset_h, float offset_v)
{
	const f32 scale = BS / 2 * cur_node.f->visual_scale;
	v3f vertices[4] = {
		v3f(-scale, -BS / 2 + scale * 2, 0),
		v3f( scale, -BS / 2 + scale * 2, 0),
		v3f( scale, -BS / 2, 0),
		v3f(-scale, -BS / 2, 0),
	};

	for (v3f &vertex : vertices) {
		vertex.rotateYZBy(opening_angle);
		vertex.Z += offset_h;
		vertex.rotateXZBy(rotation);
		vertex.Y += offset_v;
	}
	drawQuad(tile, vertices);
}

void MapblockMeshGenerator::drawFirelikeNode()
{
		v3f( size, -size, 0),
		v3f(-size, -size, 0),
	};

	for (v3f &vertex : vertices) {
		switch (wall) {
			case DWM_YP:
				vertex.Y += -size + BS/2;
				vertex.rotateXZBy(-45);
				break;
			case DWM_YN:
				vertex.Y += size - BS/2;
				vertex.rotateXZBy(45);
				break;
			case DWM_XP:
				vertex.X += -size + BS/2;
				break;
			case DWM_XN:
				vertex.X += -size + BS/2;
				vertex.rotateXZBy(180);
				break;
			case DWM_ZP:
				vertex.X += -size + BS/2;
				vertex.rotateXZBy(90);
				break;
			case DWM_ZN:
				vertex.X += -size + BS/2;
				vertex.rotateXZBy(-90);
				break;
			case DWM_S1:
				// same as DWM_YP, but rotated 90°
				vertex.Y += -size + BS/2;
				vertex.rotateXZBy(45);
				break;
			case DWM_S2:
				// same as DWM_YN, but rotated -90°
				vertex.Y += size - BS/2;
				vertex.rotateXZBy(-45);
				break;
		}
	}
	drawQuad(tile, vertices);
}

